  MESH_VIS = 3405944500,          -- CMND_SET_MESH_VISIBLE (layer, mesh, bool, idx)
  SET_PRIO = 1491630496,          -- CMND_SET_DRAW_PRIORITY (layer, idx, priority): the LAYER's order (retail 453..999)
  KIT_PRIO = 460,                 -- above the bar (453), the name / player plates (454), the user plate (455)
  -- tactic row slices (clean_hud.dll): atlas, the three sprites (left, middle, right box), the plate's sprite slot
  SLICE_ATLAS = 2640011428,       -- #/menu/200_icon/13_icon_tactics/icon_tactics.g4tx (loaded by the dock)
  SLICES = {[2] = 2875971302, [1] = 3698124400, [0] = 1365568389},   -- chd_tactic_row_l / _m / _r by instance
  PLATE_SLOT = 3889891185,        -- 0xE7DB0771: _cmd_base_t01 (and its additive overlays)
  SLICES_READY = 1351009703,              -- CMND_EVT_CHD_TACTIC_SLICES (clean_hud.dll) -> bool
  -- menu commands
  NODE_POS = 2575768773,          -- (layer, idx, node, axis 0 x / 1 y / 2 z, value): node local translation (nie 0xCE7FB0)
  NODE_SCALE = 2885415772,        -- (layer, idx, node, sx, sy): node local scale (nie 0xCE7960)
  NODE_VIS = 2158717427,          -- (layer, node, bool, idx)
  TEXT_VIS = 1505208242,          -- (layer, text node, bool, idx)
  SET_TEXT = 1083631230,          -- (layer, text node, string, idx)
  SWAP = 558735651,               -- (layer, atlas, sprite, slot sprite, 0, idx): sprite of a material slot
  PRIM_COLOR = 855211291,         -- CMND_SET_PRIM_COLOR (layer, idx, mesh, r, g, b): the mesh's tint (0..1)
  PRIM_ALPHA = 2219773080,        -- CMND_SET_PRIM_ALPHA (layer, idx, mesh, a)
  GPOS = 499270986,               -- CMND_GET_MESH_GLOBAL_POSITION (layer, idx, node) -> x, y, z
  SCISSOR_UPDATE = 1607272191,    -- (layer, idx)
  SCISSOR_COPY = 2438447022,      -- (layer, idx, from layer, from idx)
  SCISSOR_ON = 588955388,         -- (layer, idx, bool)
  LAYER_VISIBLE = 711242136,      -- (layer, idx, bool)
  FOCUS_ACTIVE = 102308320,       -- (layer) -> bool
  FOCUS_IDX = 2603265800,         -- (layer) -> focused instance
  FOCUS_SET = 3466097042,         -- (layer, idx)
  FOCUS_MARK = 1778826357,        -- (layer, idx, bool): what the retail dock sends to move its focus
  FOCUS_ENABLE = 3518307824,      -- (layer, bool)
  CURSOR_LOC = 381797568,         -- (layer, crc32("cursor"), idx, count)
  CREATE_NUM = 1175615627,        -- (layer) -> instances
  IS_OPEN = 2640875187,           -- (layer[, idx]) -> bool
  LAYER_ACTIVE = 782642007,       -- (layer) -> bool (false while the dock's layer group is suspended by a child menu)
  LAYER_POS = 1389957207,         -- CMND_SET_LAYER_LOCAL_POS (layer, x, y, z, idx): root layer, layout units, y up
  LAYER_SCALE = 3778714801,       -- CMND_SET_LAYER_LOCAL_SCALE (layer, sx, sy, sz, idx)
  EXIST_MENU = 2231168902,        -- (menu) -> bool
  ZONE = 855005857,               -- (layer, idx, bool): an instance's pointer zone on / off (retail dock move)
  POINTER = 558229292,            -- () -> x, y: the pointer, screen px, y down
  -- funcLuaCommand
  CHECK_INPUT = 4265778440,       -- (control, cmd) -> bool
  MENU_CTRL = 1332654303, MENU_CTRL_ANALOG = 2748927068, CMD_LEFT = 2765147006, CMD_DOWN = 3259546669,
  CMD_UP = 1197218715, CMD_RIGHT = 2075023265,
  SOUND = 1917805374, SE_MOVE = 2500047763,   -- sy0005: the dock's cursor sound
  TEXT_GET = 4074371074, CARD_GUIDE = 104932408,   -- t2[1].itemExplation of the retail dock (a card is focused)
  LOG = 3661580131,               -- CMND_EVT_LOG
  -- OnChangeFocus arguments of the retail FCS_CHANGE rows
  ARG_LEFT = 3842669522, ARG_RIGHT = 2682339866,
  -- menus the dock opens on top of itself (the polled keys never act while one of them is up)
  CHILDREN = {2197290544, 3977904003, 2049316981, 1313488898, 2806820415, 3358148956, 2969475803, 2679854130},
  busy = false, echo = false, logged = false, kit = {}, clipLogged = false,
  hdr = nil,                      -- nil = not decided yet, "header" = the header relayout, "panel" = header retail
  check = 0,                      -- Steps left to measure the placed header
  wait = 0,                       -- Steps waited for the team name / player plates (they open after the bar's kit)
  shift = nil, going = false, moves = 0,
  ghost = nil,                    -- {layer, idx, Steps}: the item a re-routed move left, unmarked again (CHD_Ghost)
  kitc = nil, nameOff = false, zoneLogs = 0,   -- the drawn kit (global), the team name zone switched off over it
  atdf = {x = 0, y = 0, s = 1, wait = 0, n = 0},   -- the AT / DF layer's local pos / scale as last sent
}

local function CHD_Cmd(...)
  if type(funcLuaMenuCommand) == "function" then
    return pcall(funcLuaMenuCommand, ...)
  end
  return false
end

local function CHD_Get(...)
  local ok, v = CHD_Cmd(...)
  if ok then
    return v
  end
  return nil
end

local function CHD_Lc(...)
  if type(funcLuaCommand) == "function" then
    local ok, v = pcall(funcLuaCommand, ...)
    if ok then
      return v
    end
  end
  return nil
end

local function CHD_Log(msg)
  CHD_Lc(CHD.LOG, "EVT dock_panel " .. msg)
end

local function CHD_Pack(...)
  return {n = select("#", ...), ...}
end

local function CHD_PanelOn()
  return EVT_CHD_PANEL == true and EVT_UI_PRESET ~= "off"
end

-- BetterUI 1.21.9 (owner 2026-10-13): the TÁCTICAS block (title + the 3 tactic plates) stays as in the original game:
-- no tactics row, no slices / scissor, no tactics focus re-routing; the rest of the panel layout is unchanged.
local function CHD_TacOn()
  return CHD_PanelOn() and EVT_CHD_TACTICS == true
end

local function CHD_ClipOn()
  return CHD_TacOn() and EVT_CHD_CLIP == true
end

local function CHD_ArrowsOn()
  return EVT_CHD_ARROWS == true and EVT_UI_PRESET ~= "off"
end

local function CHD_AtdfOn()
  return CHD_PanelOn() and EVT_CHD_ATDF == true
end

-- the AT / DF layer's transform as recorded (absolute: sending it again changes nothing)
local function CHD_AtdfSend()
  local st = CHD.atdf
  CHD_Cmd(CHD.LAYER_SCALE, CHD_ATDF.layer, st.s, st.s, 1, 0)
  CHD_Cmd(CHD.LAYER_POS, CHD_ATDF.layer, st.x, st.y, 0, 0)
end

-- ---- layout ------------------------------------------------------------------------------------------------------------
local CHD_ATC_TACTICS = 727258178   -- _atc_tactics01: the frame locator of the TÁCTICAS block

local function CHD_Place(layer, idx, rows, skip)
  for _, r in ipairs(rows) do
    if r[1] ~= skip then
      CHD_Cmd(CHD.NODE_POS, layer, idx, r[1], 0, r[2])
      CHD_Cmd(CHD.NODE_POS, layer, idx, r[1], 1, r[3])
      if r[4] ~= nil then
        CHD_Cmd(CHD.NODE_SCALE, layer, idx, r[1], r[4], r[5])
      end
    end
  end
end

local function CHD_HideCmdText(idx)
  CHD_Cmd(CHD.SET_TEXT, CHD.CMD, CHD.TEXT_CMD, "", idx)
  CHD_Cmd(CHD.NODE_VIS, CHD.CMD, CHD.TEXT_CMD, false, idx)
end

local function CHD_HideConfText()
  CHD_Cmd(CHD.TEXT_VIS, CHD.CONF, CHD.TEXT_BUILD, false, 0)
  CHD_Cmd(CHD.NODE_VIS, CHD.CONF, CHD.TEXT_BUILD, false, 0)
end

-- the kit's frame locator (absolute frame units), as placed last
local function CHD_KitAtc(frame)
  if CHD.kit[frame] == nil then
    for _, r in ipairs(CHD_FRAME[frame]) do
      if r[1] == CHD.ATC_UNI then
        CHD.kit[frame] = {r[2], r[3]}
      end
    end
  end
  return CHD.kit[frame]
end

-- the header layers in a mode: "header" = crest | team name | kit | player plate | «Nv.»; "panel" = retail header,
-- the kit as the retail EQUIPACIÓN box under the panel
local function CHD_ApplyHeader(layer, mode)
  local hdr = mode == "header"
  if layer == CHD.UNI then
    if hdr then
      CHD_Place(layer, 0, CHD_UNI)
      CHD_Cmd(CHD.SET_PRIO, layer, 0, CHD.KIT_PRIO)
    else
      CHD_Place(layer, 0, CHD_UNI_RETAIL)
    end
    for _, n in ipairs(CHD_UNI_HIDE) do
      CHD_Cmd(CHD.NODE_VIS, layer, n, not hdr, 0)
    end
    CHD_Cmd(CHD.MESH_VIS, layer, CHD.KIT_SHADOW, not hdr, 0)
  elseif layer == CHD.BAR then
    if hdr then
      CHD_Place(layer, 0, CHD_BAR)
      CHD_Cmd(CHD.SWAP, layer, CHD_HDR.nv_atlas, CHD_HDR.nv_sprite, CHD_HDR.nv_slot, 0, 0)
      -- round 8: the white card «Nv.» in the level digits' blue, fully opaque
      local c = CHD_HDR.nv_rgb
      CHD_Cmd(CHD.PRIM_COLOR, layer, 0, CHD_HDR.nv_mesh, c[1], c[2], c[3])
      CHD_Cmd(CHD.PRIM_ALPHA, layer, 0, CHD_HDR.nv_mesh, 1)
    else
      CHD_Place(layer, 0, CHD_BAR_RETAIL)
      CHD_Cmd(CHD.SWAP, layer, CHD_HDR_CHECK.nv_atlas, CHD_HDR.nv_slot, CHD_HDR.nv_slot, 0, 0)
      CHD_Cmd(CHD.PRIM_COLOR, layer, 0, CHD_HDR.nv_mesh, 1, 1, 1)   -- the retail label carries its own blue
    end
  elseif layer == CHD.NAME then
    CHD_Place(layer, 0, hdr and CHD_NAME or CHD_NAME_RETAIL)
  end
end

-- every node edit of one layer instance (absolute values: applying it again changes nothing)
local function CHD_Apply(layer, idx)
  idx = idx or 0
  if CHD_PanelOn() then
    if CHD_FRAME[layer] ~= nil then
      if idx == 0 then
        CHD_Place(layer, 0, CHD_FRAME[layer], (not CHD_TacOn()) and CHD_ATC_TACTICS or nil)
        local k = CHD.hdr == "header" and CHD_KitAtc(layer) or CHD_UNI_PANEL[layer]
        if k ~= nil then
          CHD_Cmd(CHD.NODE_POS, layer, 0, CHD.ATC_UNI, 0, k[1])
          CHD_Cmd(CHD.NODE_POS, layer, 0, CHD.ATC_UNI, 1, k[2])
        end
      end
    elseif layer == CHD.BASE then
      if CHD_TacOn() then
        CHD_Place(layer, 0, CHD_BASE)
      end
    elseif layer == CHD.CMD then
      if not CHD_TacOn() then
        return
      end
      if idx <= 2 then
        CHD_Place(layer, idx, CHD_ClipOn() and CHD_CMD_CLIP[idx] or CHD_CMD_BOX)
        CHD_HideCmdText(idx)
        if not CHD_ClipOn() and CHD_Lc(CHD.SLICES_READY) == true then
          CHD_Cmd(CHD.SWAP, layer, CHD.SLICE_ATLAS, CHD.SLICES[idx], CHD.PLATE_SLOT, 0, idx)
        end
      end
    elseif layer == CHD.TAC then
      if idx <= 2 and CHD_TacOn() then
        CHD_Place(layer, idx, CHD_FOCUS)
      end
    elseif layer == CHD.FORM then
      CHD_Place(layer, 0, CHD_FORM)
    elseif layer == CHD.CONF then
      CHD_Place(layer, 0, CHD_CONF)
      CHD_HideConfText()
    elseif (layer == CHD.UNI or layer == CHD.BAR or layer == CHD.NAME) and CHD.hdr ~= nil then
      CHD_ApplyHeader(layer, CHD.hdr)
    end
  end
  if layer == CHD_ATDF.layer and (CHD.atdf.x ~= 0 or CHD.atdf.y ~= 0 or CHD.atdf.s ~= 1) then
    CHD_AtdfSend()                -- keep the engine on the recorded transform (Step corrects it from there)
  end
  if layer == CHD.DOCKNO and CHD_ArrowsOn() then
    CHD_Place(layer, 0, CHD_DOCKNO)
  end
  if not CHD.logged and (CHD_PanelOn() or CHD_ArrowsOn()) then
    CHD.logged = true
    CHD_Log("on (panel " .. tostring(CHD_PanelOn()) .. ", clip " .. tostring(CHD_ClipOn()) .. ", arrows "
      .. tostring(CHD_ArrowsOn()) .. ")")
  end
end

-- every Step: each box's plate clipped to its box (the box's frame layer recomputes its rectangle first: the dock's
-- slide-in / dock switch move them)
local CHD_G
local function CHD_Clip()
  for i = 0, 2 do
    if CHD_Get(CHD.IS_OPEN, CHD.CMD, i) == true and CHD_Get(CHD.IS_OPEN, CHD.TAC, i) == true then
      -- the frame must be somewhere on screen, else the box is left unclipped
      local fx, fy = CHD_G(CHD.TAC, i, CHD.TOUCH_LIST)
      if not CHD.clipLogged then
        CHD_Log("clip box " .. i .. " frame at " .. tostring(fx) .. "," .. tostring(fy))
        if i == 2 then
          CHD.clipLogged = true
        end
      end
      if fx ~= nil and math.abs(fx) < 4096 and math.abs(fy) < 4096 then
        CHD_Cmd(CHD.SCISSOR_UPDATE, CHD.TAC, i)
        CHD_Cmd(CHD.SCISSOR_COPY, CHD.CMD, i, CHD.TAC, i)
        CHD_Cmd(CHD.SCISSOR_ON, CHD.CMD, i, true)
      else
        CHD_Cmd(CHD.SCISSOR_ON, CHD.CMD, i, false)
      end
    end
  end
end

CHD_G = function(layer, idx, node)
  local ok, x, y = CHD_Cmd(CHD.GPOS, layer, idx, node)
  if ok and type(x) == "number" and type(y) == "number" then
    return x, y
  end
  return nil
end

-- every Step: the kit's centre onto its place between the team name and player plates, measured in global units (the bar's and the field's
-- scales come from known node distances, so another mod scaling / moving the pitch or the bar changes nothing)
local function CHD_FixKit()
  if CHD.hdr ~= "header" or CHD_Get(CHD.IS_OPEN, CHD.BAR, 0) ~= true or CHD_Get(CHD.IS_OPEN, CHD.UNI, 0) ~= true then
    return
  end
  local bx, by = CHD_G(CHD.BAR, 0, CHD.POS_BASE)
  local ex, ey = CHD_G(CHD.BAR, 0, CHD_HDR.crest)
  local ux, uy = CHD_G(CHD.UNI, 0, CHD.POS_BASE)
  local ix, iy = CHD_G(CHD.UNI, 0, CHD.KIT_ICON)
  if bx == nil or ex == nil or ux == nil or ix == nil then
    return
  end
  local cr = CHD_BAR_CREST
  local kbx, kby = (ex - bx) / cr[1], (ey - by) / cr[2]
  local kux, kuy = (ix - ux) / CHD_UNI[1][2], (iy - uy) / CHD_UNI[1][3]
  if math.abs(kbx) < 0.05 or math.abs(kby) < 0.05 or math.abs(kux) < 0.05 or math.abs(kuy) < 0.05 then
    return
  end
  -- where the kit is drawn now (global units: centre, half sizes of its focus frame), for the pointer guard
  CHD.kitc = {ux + CHD_HDR.ux * kux, uy + CHD_HDR.uy * kuy, CHD_UNI[3][4] / 2 * math.abs(kux),
    CHD_UNI[3][5] / 2 * math.abs(kuy)}
  -- the kit's centre: midway between the measured team name plate's right edge and the player plate's left edge
  -- (where the retail «Nv. EQUIPO» sat), in bar units; the layout's value only while the plates are not measurable
  local kx = CHD_HDR.kx
  local nx = CHD_G(CHD.NAME, 0, CHD.NAME_BASE)
  local px = CHD_G(CHD.DECK, 0, CHD.DECK_BASE)
  if nx ~= nil and px ~= nil then
    local gl, gr = (nx - bx) / kbx + CHD_NAME[1][4], (px - bx) / kbx
    if gr > gl and gr - gl < 600 then
      kx = (gl + gr) / 2
    end
  end
  -- the kit's centre (CHD_HDR.ux / uy in its layer: the retail hit zone's centre) onto the target, so the layer
  -- origin goes there minus that offset
  local tx, ty = bx + kx * kbx - CHD_HDR.ux * kux, by + CHD_HDR.ky * kby - CHD_HDR.uy * kuy
  local dx, dy = (tx - ux) / kux, (ty - uy) / kuy
  if math.abs(dx) < 0.5 and math.abs(dy) < 0.5 then
    return
  end
  for _, frame in ipairs(CHD.FRAMES) do
    if CHD_Get(CHD.IS_OPEN, frame, 0) == true then
      local k = CHD_KitAtc(frame)
      if k ~= nil then
        k[1], k[2] = k[1] + dx, k[2] + dy
        CHD_Cmd(CHD.NODE_POS, frame, 0, CHD.ATC_UNI, 0, k[1])
        CHD_Cmd(CHD.NODE_POS, frame, 0, CHD.ATC_UNI, 1, k[2])
      end
    end
  end
end

-- ---- focus ---------------------------------------------------------------------------------------------------------------
local function CHD_Active(layer)
  return CHD_Get(CHD.FOCUS_ACTIVE, layer) == true
end

local function CHD_Idx(layer)
  local v = CHD_Get(CHD.FOCUS_IDX, layer)
  if type(v) == "number" then
    return v
  end
  return 0
end

local function CHD_Num(layer)
  local v = CHD_Get(CHD.CREATE_NUM, layer)
  if type(v) == "number" then
    return v
  end
  return 1
end

local function CHD_Open(layer, idx)
  return CHD_Get(CHD.IS_OPEN, layer, idx or 0) == true
end

-- every Step (one correction, then 2 Steps to let the global positions follow): the AT / DF block (its _pos_scl01,
-- the centre of its line) onto CHD_ATDF.tx / ty field units from the keeper's spot _pos_formation01, the block scaled
-- to CHD_ATDF.scale of the field's scale. Everything measured in global units, so the dock's slide-in, a dock switch
-- or another mod moving / scaling the pitch or the block's layout only changes where it lands, not that it is under
-- the keeper. Only on the 11v11 pitch; otherwise the layer goes back to its retail transform.
local function CHD_Atdf()
  local A, st = CHD_ATDF, CHD.atdf
  if CHD_Get(CHD.IS_OPEN, A.layer, 0) ~= true then
    return
  end
  if not CHD_AtdfOn() or CHD_Get(CHD.IS_OPEN, A.frame, 0) ~= true then
    if st.x ~= 0 or st.y ~= 0 or st.s ~= 1 then
      st.x, st.y, st.s = 0, 0, 1
      CHD_AtdfSend()
    end
    return
  end
  if st.wait > 0 then
    st.wait = st.wait - 1
    return
  end
  local fbx, fby = CHD_G(A.frame, 0, CHD.POS_BASE)
  local ffx, ffy = CHD_G(A.frame, 0, A.field)
  local gx, gy = CHD_G(A.frame, 0, A.gk)
  local abx = CHD_G(A.layer, 0, CHD.POS_BASE)
  local asx, asy = CHD_G(A.layer, 0, A.scl)
  local _, any = CHD_G(A.layer, 0, A.num)
  if fbx == nil or ffx == nil or gx == nil or abx == nil or asx == nil or any == nil then
    return
  end
  local kfx, kfy = (ffx - fbx) / A.fx, (ffy - fby) / A.fy        -- global units per field unit
  local kax, kay = (asx - abx) / A.dx / st.s, (any - asy) / A.dy / st.s   -- per unscaled layer unit
  if math.abs(kfx) < 0.05 or math.abs(kfy) < 0.05 or math.abs(kax) < 0.05 or math.abs(kay) < 0.05 then
    return
  end
  local s = A.scale * kfy / kay
  if s < 0.2 or s > 1.5 then
    s = A.scale
  end
  local tx, ty = gx + A.tx * kfx, gy + A.ty * kfy
  local dx, dy = (tx - asx) / kax, (ty - asy) / kay
  if math.abs(s - st.s) < 0.005 and math.abs(dx) < 0.5 and math.abs(dy) < 0.5 then
    return
  end
  if math.abs(s - st.s) >= 0.005 then
    st.s = s                      -- the scale first (about the layer origin): the position is measured again after it
  else
    st.x, st.y = st.x + dx, st.y + dy
  end
  CHD_AtdfSend()
  st.wait = 2
  if st.n < 12 then
    st.n = st.n + 1
    CHD_Log(string.format("atdf -> pos %.1f, %.1f scale %.3f (block was %.1f, %.1f from target)", st.x, st.y, st.s,
      dx, dy))
  end
end

local function CHD_ConfShown()
  if not CHD_Open(CHD.CONF, 0) then
    return false
  end
  if type(IsVisibleTeamBuildTypeIcon) == "function" then
    local ok, v = pcall(IsVisibleTeamBuildTypeIcon, CHD.CONF)
    if ok and v == false then
      return false
    end
  end
  return true
end

-- the focus lands on (layer, idx): the retail marker, the engine's own index if the marker did not move it, then the
-- dock's OnChangeFocus (run by the engine's echo, else here) for its cursor / guide line / tactic info / balloon
local function CHD_SetFocus(layer, idx)
  CHD.busy, CHD.echo = true, false
  CHD_Cmd(CHD.FOCUS_MARK, layer, idx, true)
  if CHD_Idx(layer) ~= idx then
    CHD_Cmd(CHD.FOCUS_SET, layer, idx)
  end
  CHD.busy = false
  if not CHD.echo and type(OnChangeFocus) == "function" then
    pcall(OnChangeFocus, layer, idx)
  end
end

-- one instance of the tactics row to another, as the engine's own step inside a layer
local function CHD_TacStep(from, to)
  CHD_Cmd(3781155141 --[[CMND_PLAY_ANIME_TYPE]], CHD.TAC, from, 1286797620 --[[Active]], 2, 973515837 --[[button]])
  CHD_Cmd(3781155141 --[[CMND_PLAY_ANIME_TYPE]], CHD.TAC, from, 2734777837 --[[Focus]], 2, 973515837 --[[button]])
  CHD_Cmd(CHD.CURSOR_LOC, CHD.TAC, CHD.CURSOR, to, CHD_Num(CHD.TAC))
  CHD_SetFocus(CHD.TAC, to)
end

-- the focus mark and highlight off on an instance that no longer holds the focus (what the retail OnMouseMove does
-- to the item the pointer leaves, plus the out animations of OnFocusLayerShift)
local function CHD_Unfocus(layer, idx)
  CHD.busy = true
  CHD_Cmd(CHD.FOCUS_MARK, layer, idx, false)
  CHD.busy = false
  CHD_Cmd(3781155141 --[[CMND_PLAY_ANIME_TYPE]], layer, idx, 1286797620 --[[Active]], 2, 973515837 --[[button]])
  CHD_Cmd(3781155141 --[[CMND_PLAY_ANIME_TYPE]], layer, idx, 2734777837 --[[Focus]], 2, 973515837 --[[button]])
end

-- (from, fi) -> (to, ti) like a retail focus shift row: the dock's OnFocusLayerShift (plates, cursor trace, control
-- focus), the control focus, the cursor, the focus itself. `from` is unmarked: when it is the transient target of a
-- retail shift row this layout re-routes (FORMACIÓN DOWN -> CONF., kit LEFT -> CONF., team name RIGHT -> player
-- plate…), the engine had marked it and played its focus-in, and without this it kept its frame next to the real
-- focus (two items highlighted, in game 1.14.0). It is unmarked again for CHD_GHOST_STEPS Steps (CHD_Ghost): the
-- engine's own focus-in of the shift can land after this Step.
local CHD_GHOST_STEPS = 3
local function CHD_Go(from, fi, to, ti)
  if CHD.moves < 80 then
    CHD.moves = CHD.moves + 1
    CHD_Log("focus " .. tostring(from) .. "[" .. tostring(fi) .. "] -> " .. tostring(to) .. "[" .. tostring(ti) .. "]")
  end
  CHD.going = true
  if type(OnFocusLayerShift) == "function" then
    pcall(OnFocusLayerShift, from, fi, to, ti)
  end
  CHD.going = false
  CHD_Cmd(CHD.FOCUS_ENABLE, from, false)
  CHD_Cmd(CHD.FOCUS_ENABLE, to, true)
  CHD_Cmd(CHD.CURSOR_LOC, to, CHD.CURSOR, ti, CHD_Num(to))
  CHD_SetFocus(to, ti)
  if from ~= to then
    CHD_Unfocus(from, fi)
    CHD.ghost = {from, fi, CHD_GHOST_STEPS}
  end
end

-- every Step after a CHD_Go: the left item unmarked again while it does not hold the focus
local function CHD_Ghost()
  local g = CHD.ghost
  if g == nil then
    return
  end
  g[3] = g[3] - 1
  if g[3] <= 0 then
    CHD.ghost = nil
  end
  if not CHD_Active(g[1]) then
    CHD_Unfocus(g[1], g[2])
  else
    CHD.ghost = nil                -- the focus came back to it: leave it alone
  end
end

-- the nearest card of the pitch / bench from (layer, idx) in a retail direction (1 up, 2 down, 3 left, 4 right; the
-- retail MoveToOtherLayer / CalcMoveFocusLayerIdx: positions measured, a 37° cone) -> card index or nil
local function CHD_CardFrom(dir, layer, idx)
  if type(MoveToOtherLayer) ~= "function" then
    return nil
  end
  local ok, ci, cl = pcall(MoveToOtherLayer, dir, layer, idx, CHD.CARDS, CHD_Num(CHD.CARDS), 37, true)
  if not ok or ci == nil or ci == -1 or cl ~= CHD.CARDS then
    return nil
  end
  return ci
end

-- the focus onto pitch card `ci` the way the retail moves there from the panel (control focus, cursor, mark, the
-- dock's selected card, its guide line, no build balloon); `from` = the layer the engine / this graft left
local function CHD_ToCard(from, fi, ci)
  CHD_Cmd(CHD.FOCUS_ENABLE, from, false)
  CHD_Cmd(CHD.FOCUS_ENABLE, CHD.CARDS, true)
  CHD_Cmd(CHD.CURSOR_LOC, CHD.CARDS, CHD.CURSOR, ci, CHD_Num(CHD.CARDS))
  if type(SetIsTeamDockTop) == "function" then
    pcall(SetIsTeamDockTop, false)
  end
  if type(UpdateChangeFocusLayer) == "function" then
    pcall(UpdateChangeFocusLayer, CHD.CARDS, ci, ci, CHD.CARDS)
  end
  if type(SetSelectCharaIdx) == "function" then
    pcall(SetSelectCharaIdx, ci)
  end
  local text = CHD_Lc(CHD.TEXT_GET, CHD.CARD_GUIDE)
  if type(text) == "string" then
    CHD_Cmd(CHD.SET_TEXT, CHD.GUIDE_LINE, CHD.GUIDE_NODE, text, 0)
  end
  CHD_Cmd(CHD.LAYER_VISIBLE, CHD.BALLOON, 0, false)
  if from ~= CHD.CARDS then
    CHD_Unfocus(from, fi)
    CHD.ghost = {from, fi, CHD_GHOST_STEPS}
  end
end

-- header mode, FORMACIÓN DOWN: the panel has no row below FORMACIÓN | CONF. (the kit is in the header), so the next
-- row down is the nearest card below it (retail measure, as the tactics' UP to the coach card); none -> FORMACIÓN
-- keeps the focus. `at` / `ai` = where the engine's retail row put the focus (CONF. after the shift), unmarked
local function CHD_FormDown(at, ai)
  local ci = CHD_CardFrom(2, CHD.FORM, 0)
  if ci ~= nil then
    if CHD.moves < 80 then
      CHD.moves = CHD.moves + 1
      CHD_Log("focus " .. tostring(at) .. "[" .. tostring(ai) .. "] -> card " .. tostring(ci) .. " (FORMACIÓN DOWN)")
    end
    CHD_ToCard(at, ai, ci)
    if at ~= CHD.FORM then
      CHD_Unfocus(CHD.FORM, 0)
    end
  elseif at ~= CHD.FORM then
    CHD_Go(at, ai, CHD.FORM, 0)
  end
end

-- CONF. DE EQUIPO -> the pitch on the right: the retail EQUIPACIÓN move (OnChangeFocus, right) from the CONF. box
local function CHD_ConfToPitch(at, ai)
  at, ai = at or CHD.CONF, ai or 0
  local ci = CHD_CardFrom(4, CHD.CONF, 0)
  if ci ~= nil then
    CHD_ToCard(at, ai, ci)
    if at ~= CHD.CONF then
      CHD_Unfocus(CHD.CONF, 0)
    end
  elseif at ~= CHD.CONF then
    CHD_Go(at, ai, CHD.CONF, 0)   -- no card on the right: CONF. keeps the focus
  end
end

-- every Step (header mode): the team name plate's pointer zone is its layout rectangle (468 px from the plate's left
-- edge, it does not follow the narrowed plate), so it runs on over the whole kit and could take the kit's hover /
-- click. While the pointer is on the drawn kit the name plate's zone is switched off (retail 855005857, as the dock
-- does for every zone during a dock move), and back on when it leaves. Pointer = screen px, y down; global positions
-- are compared with (x, -y) as the retail players_universe_menu does. The first readings are logged.
local function CHD_PointerGuard()
  if CHD.hdr ~= "header" or CHD.kitc == nil or not CHD_Open(CHD.NAME, 0) then
    return
  end
  if CHD_Get(CHD.LAYER_ACTIVE, CHD.UNI) == false then
    return                        -- a child menu is up / the dock is moving: the retail owns the zones
  end
  local ok, x, y = CHD_Cmd(CHD.POINTER)
  if not ok or type(x) ~= "number" or type(y) ~= "number" then
    return
  end
  local k = CHD.kitc
  local on = math.abs(x - k[1]) <= k[3] and math.abs(-y - k[2]) <= k[4]
  if on == CHD.nameOff then
    return
  end
  CHD.nameOff = on
  CHD_Cmd(CHD.ZONE, CHD.NAME, 0, not on)
  if CHD.zoneLogs < 8 then
    CHD.zoneLogs = CHD.zoneLogs + 1
    CHD_Log(string.format("pointer %.0f,%.0f kit %.0f,%.0f (+-%.0f,%.0f): team name zone %s", x, y, k[1], k[2], k[3],
      k[4], on and "off" or "on"))
  end
end

-- every Step (2026-10-13, owner: the pointer on CONF. DE EQUIPO lit FORMACIÓN): the same rule for the FORMACIÓN | CONF.
-- row. Their engine zones are their retail rectangles (FORMACIÓN 398 px, centred on the retail text; CONF. 194 x 130,
-- centred on the drawn box by the generator), so each runs over the other's drawn box. While the pointer is on one
-- drawn box, the other one's zone is switched off; anywhere else both are on (retail). Drawn box = the box mesh (first
-- row of CHD_FORM / CHD_CONF: top-left + size) measured in global units, the scale from its _pos_atc_free01 row.
CHD.FREE_NODE = 4293674698        -- _pos_atc_free01
CHD.boxOff = {}
function CHD.Drawn(layer, rows)
  local base, ref = rows[1], nil
  for _, r in ipairs(rows) do
    if r[1] == CHD.FREE_NODE then
      ref = r
    end
  end
  if ref == nil or ref[2] == base[2] or ref[3] == base[3] or not CHD_Open(layer, 0) then
    return nil
  end
  local gx, gy = CHD_G(layer, 0, base[1])
  local fx, fy = CHD_G(layer, 0, ref[1])
  if gx == nil or fx == nil then
    return nil
  end
  local kx, ky = (fx - gx) / (ref[2] - base[2]), (fy - gy) / (ref[3] - base[3])
  if math.abs(kx) < 0.05 or math.abs(ky) < 0.05 then
    return nil
  end
  local x1, y1 = gx + base[4] * kx, gy - base[5] * ky
  return {math.min(gx, x1), math.max(gx, x1), math.min(gy, y1), math.max(gy, y1)}
end

function CHD.BoxGuard()
  if not CHD_PanelOn() or CHD_Get(CHD.LAYER_ACTIVE, CHD.FORM) == false then
    return                        -- a child menu is up / the dock is moving: the retail owns the zones
  end
  local off = {}
  if CHD_ConfShown() then
    local ok, x, y = CHD_Cmd(CHD.POINTER)
    if ok and type(x) == "number" and type(y) == "number" then
      local f, c = CHD.Drawn(CHD.FORM, CHD_FORM), CHD.Drawn(CHD.CONF, CHD_CONF)
      local function inside(b)
        return b ~= nil and x >= b[1] and x <= b[2] and -y >= b[3] and -y <= b[4]
      end
      local inF, inC = inside(f), inside(c)
      off[CHD.FORM] = inC and not inF
      off[CHD.CONF] = inF and not inC
    end
  end
  for _, layer in ipairs({CHD.FORM, CHD.CONF}) do
    local o, was = off[layer] == true, CHD.boxOff[layer] == true
    if o or was then              -- never touches a zone this guard did not switch off
      if was ~= o and CHD.zoneLogs < 16 then
        CHD.zoneLogs = CHD.zoneLogs + 1
        CHD_Log("pointer box guard: zone of " .. tostring(layer) .. (o and " off" or " on"))
      end
      CHD.boxOff[layer] = o
      CHD_Cmd(CHD.ZONE, layer, 0, not o)
    end
  end
end

-- ---- wrappers --------------------------------------------------------------------------------------------------------------
local function CHD_After(name, after)
  local prev = rawget(_ENV, name)
  if type(prev) ~= "function" then
    return
  end
  rawset(_ENV, name, function(...)
    local r = CHD_Pack(prev(...))
    local ok, err = pcall(after, ...)
    if not ok then
      CHD_Log("error " .. name .. " " .. tostring(err))
    end
    return table.unpack(r, 1, r.n)
  end)
end

CHD_After("OnSetupLayer", function(a1, a2)
  CHD_Apply(a1, a2)
end)
CHD_After("OnOpenLayer", function(a1, a2)
  CHD_Apply(a1, a2)
end)
-- the retail sets the tactic's name and plate per instance (setup, open, every refresh)
CHD_After("SetupTacticsLayer", function(a1, a2)
  if a1 == CHD.CMD then
    CHD_Apply(CHD.CMD, a2)
  end
end)
-- the INCLUDE shows the team config's name again on every refresh
CHD_After("UpdateTeamBuildTypeInfo", function(a1, a2, a3)
  if CHD_PanelOn() and (a3 == nil or a3 == CHD.CONF) then
    CHD_HideConfText()
  end
end)
-- the retail shows both kit sprites on every refresh: the drop shadow off again after it (in header mode it also has
-- size 0 in CHD_UNI: after a dock switch the kit icon finishes loading after this and shows the shadow again)
CHD_After("SetupUniformIcom", function(a1, a2)
  if CHD_PanelOn() and CHD.hdr == "header" and (a1 == nil or a1 == CHD.UNI) then
    CHD_Cmd(CHD.MESH_VIS, CHD.UNI, CHD.KIT_SHADOW, false, a2 or 0)
  end
end)
-- the retail writes the team level / name on every refresh of the bar: the «Nv.» sprite again after it
CHD_After("SetupTeamDockTeamNameBar", function()
  CHD_Apply(CHD.BAR, 0)
end)

local chd_prev_change = rawget(_ENV, "OnChangeFocus")
if type(chd_prev_change) == "function" then
  rawset(_ENV, "OnChangeFocus", function(a1, a2, ...)
    if CHD.busy then
      CHD.echo = true
    elseif CHD_PanelOn() and (a2 == CHD.ARG_LEFT or a2 == CHD.ARG_RIGHT) and CHD_Active(a1) then
      if a1 == CHD.TAC and CHD_TacOn() then
        local i = CHD_Idx(CHD.TAC)
        local j = (a2 == CHD.ARG_LEFT) and i + 1 or i - 1   -- instance 2 is the left box
        if j >= 0 and j <= 2 and CHD_Open(CHD.TAC, j) then
          CHD_TacStep(i, j)
          return
        end
      elseif a1 == CHD.FORM and a2 == CHD.ARG_RIGHT and CHD_ConfShown() then
        CHD_Go(CHD.FORM, 0, CHD.CONF, 0)
        return
      elseif a1 == CHD.UNI and a2 == CHD.ARG_RIGHT and CHD.hdr == "header" and CHD_Open(CHD.DECK, 0) then
        CHD_Go(CHD.UNI, 0, CHD.DECK, 0)
        return
      end
    end
    return chd_prev_change(a1, a2, ...)
  end)
end

-- CMD_FCS_NEXT (tactics UP, FORMACIÓN DOWN); return 1 = handled, the engine does not step
local chd_prev_inc = rawget(_ENV, "MoveFocusInc")
rawset(_ENV, "MoveFocusInc", function(a1, a2, ...)
  if CHD_PanelOn() then
    if a2 == CHD.TAC and CHD_TacOn() then
      -- the retail moves up only from its top row (instance 2): run it as if the focus were there
      if type(chd_prev_inc) == "function" then
        local real = rawget(_ENV, "funcLuaMenuCommand")
        if type(real) == "function" then
          rawset(_ENV, "funcLuaMenuCommand", function(c, l, ...)
            if c == CHD.FOCUS_IDX and l == CHD.TAC then
              return 2
            end
            return real(c, l, ...)
          end)
        end
        local ok, err = pcall(chd_prev_inc, a1, a2, ...)
        if type(real) == "function" then
          rawset(_ENV, "funcLuaMenuCommand", real)
        end
        if not ok then
          CHD_Log("error MoveFocusInc " .. tostring(err))
        end
      end
      return 1
    elseif a2 == CHD.FORM then
      if CHD.hdr ~= "header" then
        if CHD_Open(CHD.UNI, 0) then
          CHD_Go(CHD.FORM, 0, CHD.UNI, 0)   -- panel mode: the kit is under the panel
        end
      else
        CHD_FormDown(CHD.FORM, 0)   -- header mode: the card below, else nothing (the retail row would go to CONF.)
      end
      return 1
    elseif a2 == CHD.NAME and CHD.hdr == "header" and CHD_Open(CHD.UNI, 0) then
      CHD_Go(CHD.NAME, 0, CHD.UNI, 0)   -- team name RIGHT: the kit (the retail row goes to the player plate)
      return 1
    end
  end
  if type(chd_prev_inc) == "function" then
    return chd_prev_inc(a1, a2, ...)
  end
end)

-- CMD_FCS_BACK (tactics DOWN, FORMACIÓN UP, EQUIPACIÓN UP)
local chd_prev_dec = rawget(_ENV, "MoveFocusDec")
rawset(_ENV, "MoveFocusDec", function(a1, a2, ...)
  if CHD_PanelOn() then
    if a2 == CHD.TAC and CHD_TacOn() then
      local i = CHD_Idx(CHD.TAC)
      if i == 0 and CHD_ConfShown() then
        CHD_Go(CHD.TAC, 0, CHD.CONF, 0)
        return 1
      elseif i ~= 0 and CHD_Open(CHD.FORM, 0) then
        CHD_Go(CHD.TAC, i, CHD.FORM, 0)
        return 1
      end
    elseif a2 == CHD.FORM and CHD_TacOn() and CHD_Open(CHD.TAC, 2) then
      CHD_Go(CHD.FORM, 0, CHD.TAC, 2)
      return 1
    elseif a2 == CHD.UNI and CHD.hdr == "header" then
      return 1                    -- the header has nothing above (the retail row would go to FORMACIÓN)
    elseif a2 == CHD.DECK and CHD.hdr == "header" and CHD_Open(CHD.UNI, 0) then
      CHD_Go(CHD.DECK, 0, CHD.UNI, 0)   -- player plate LEFT: the kit (the retail row goes to the team name)
      return 1
    end
  end
  if type(chd_prev_dec) == "function" then
    return chd_prev_dec(a1, a2, ...)
  end
end)

-- CMD_FCS_MTX_* (CONF. DE EQUIPO up / down / right, EQUIPACIÓN left): (layer, dx, dy) with dx > 0 right, dy < 0 up
local chd_prev_mtx = rawget(_ENV, "MoveFocusMtx")
rawset(_ENV, "MoveFocusMtx", function(a1, a2, a3, ...)
  if CHD_PanelOn() and type(a2) == "number" and type(a3) == "number" then
    if a1 == CHD.CONF then
      if a3 < 0 then
        if CHD_Open(CHD.TAC, 0) then
          CHD_Go(CHD.CONF, 0, CHD.TAC, 0)
        end
      elseif a3 > 0 then
        if CHD.hdr ~= "header" and CHD_Open(CHD.UNI, 0) then
          CHD_Go(CHD.CONF, 0, CHD.UNI, 0)   -- panel mode: the kit is under the panel
        end
      elseif a2 > 0 then
        CHD_ConfToPitch()
      elseif a2 < 0 then
        CHD_Go(CHD.CONF, 0, CHD.FORM, 0)
      end
      return 1
    elseif a1 == CHD.UNI and a2 < 0 and CHD.hdr == "header" then
      if CHD_Open(CHD.NAME, 0) then
        CHD_Go(CHD.UNI, 0, CHD.NAME, 0)
      end
      return 1
    end
  end
  if type(chd_prev_mtx) == "function" then
    return chd_prev_mtx(a1, a2, a3, ...)
  end
end)

-- keys without a retail input row on that layer: CONF. LEFT, EQUIPACIÓN DOWN. Read while the layer holds the focus and
-- no child menu is up
local function CHD_Key(cmd)
  return CHD_Lc(CHD.CHECK_INPUT, CHD.MENU_CTRL, cmd) == true or CHD_Lc(CHD.CHECK_INPUT, CHD.MENU_CTRL_ANALOG, cmd) == true
end

local function CHD_Free(layer)
  if not CHD_Active(layer) or CHD_Get(CHD.LAYER_ACTIVE, layer) == false then
    return false
  end
  for _, m in ipairs(CHD.CHILDREN) do
    if CHD_Get(CHD.EXIST_MENU, m) == true then
      return false
    end
  end
  return true
end

local function CHD_Poll()
  if CHD_Free(CHD.CONF) and CHD_Key(CHD.CMD_LEFT) then
    CHD_Go(CHD.CONF, 0, CHD.FORM, 0)
    CHD_Lc(CHD.SOUND, CHD.SE_MOVE)
  elseif CHD.hdr == "header" and CHD_Free(CHD.UNI) and CHD_Key(CHD.CMD_DOWN) and CHD_Open(CHD.TAC, 0) then
    CHD_Go(CHD.UNI, 0, CHD.TAC, 0)
    CHD_Lc(CHD.SOUND, CHD.SE_MOVE)
  end
end

-- ---- header mode: decided once the bar's layers are open, then the placed header is measured ----------------------
local function CHD_SetMode(mode, why)
  CHD.hdr = mode
  CHD_Log("header " .. mode .. " (" .. why .. ")")
  for _, L in ipairs({CHD.BAR, CHD.NAME, CHD.UNI}) do
    if CHD_Open(L, 0) then
      CHD_ApplyHeader(L, mode)
    end
  end
  for _, frame in ipairs(CHD.FRAMES) do
    if CHD_Open(frame, 0) then
      local k = mode == "header" and CHD_KitAtc(frame) or CHD_UNI_PANEL[frame]
      CHD_Cmd(CHD.NODE_POS, frame, 0, CHD.ATC_UNI, 0, k[1])
      CHD_Cmd(CHD.NODE_POS, frame, 0, CHD.ATC_UNI, 1, k[2])
    end
  end
end

-- a plate is there once its layer is open and not hidden. The bar opens the kit and the plates in one OnOpenLayer,
-- but the plates (fonts) finish loading / become visible a few Steps after the kit: in game (1.6.0) the first Step
-- with the bar and the kit open still saw no team name plate on every dock, so a missing plate only counts once it
-- is still missing after CHD_PLATE_WAIT Steps
local CHD_PLATE_WAIT = 120
local function CHD_Plate(layer)
  local open = CHD_Open(layer, 0)
  local vis = open and CHD_Get(CHD.IS_VISIBLE, layer, 0) ~= false
  return open and vis, open
end

local function CHD_Decide()
  if CHD.hdr ~= nil or not CHD_Open(CHD.BAR, 0) or not CHD_Open(CHD.UNI, 0) then
    return
  end
  if rawget(_ENV, "g_parentMenuId") == CHD.VR_MENU then
    CHD_SetMode("panel", "opened from the Victory Road")
    return
  end
  local name, nameOpen = CHD_Plate(CHD.NAME)
  local deck, deckOpen = CHD_Plate(CHD.DECK)
  if name and deck then
    CHD_SetMode("header", "crest | team name | kit | player plate | Nv., after " .. CHD.wait .. " Step(s)")
    CHD.check = 30
    return
  end
  CHD.wait = CHD.wait + 1
  if CHD.wait < CHD_PLATE_WAIT then
    return                        -- not decided yet: the header stays retail meanwhile
  end
  if not name then
    CHD_SetMode("panel", "no team name plate after " .. CHD.wait .. " Steps (open " .. tostring(nameOpen) .. ")")
  else
    CHD_SetMode("panel", "no player plate after " .. CHD.wait .. " Steps (open " .. tostring(deckOpen) .. ")")
  end
end

-- the placed team name and player plates where this layout put them (global units, the bar's measured scale), logged
-- once 30 Steps after the header mode is set. Log only: the 1.6.0 guard fell back to the retail header when they
-- were off, but the plates are attached layers whose global positions lag the bar's by a frame, so the Step after
-- the relayout measured them exactly at their retail places (-542 / 176) on every dock (in game 2026-10-03 12:21)
local function CHD_Check()
  if CHD.check <= 0 or CHD.hdr ~= "header" then
    return
  end
  CHD.check = CHD.check - 1
  if CHD.check > 0 then
    return
  end
  local bx, by = CHD_G(CHD.BAR, 0, CHD.POS_BASE)
  local ex = CHD_G(CHD.BAR, 0, CHD_HDR.crest)
  local nx = CHD_G(CHD.NAME, 0, CHD.NAME_BASE)
  local dx = CHD_G(CHD.DECK, 0, CHD.DECK_BASE)
  if bx == nil or ex == nil or nx == nil or dx == nil then
    return                        -- not measurable: kept
  end
  local k = (ex - bx) / CHD_BAR_CREST[1]
  if math.abs(k) < 0.05 then
    return
  end
  local en, ed = (nx - bx) / k, (dx - bx) / k
  CHD_Log(string.format("header measured: team name %.0f / player plate %.0f (layout %.0f / %.0f)",
    en, ed, CHD_HDR_CHECK.name_l, CHD_HDR_CHECK.deck_l))
end

-- the retail focus SHIFT rows (setting) this layout re-routes: the engine moved the focus from -> to by itself;
-- the focus goes on to this layout's target (only if it is still where the engine put it): at once for a key shift,
-- else on the next Step (see the OnFocusLayerShift wrapper below)
local function CHD_Redirect(sh)
  local f, fi, t, ti = sh[1], sh[2], sh[3], sh[4]
  if not CHD_Active(t) then
    return
  end
  local hdr = CHD.hdr == "header"
  if hdr and f == CHD.NAME and t == CHD.DECK and CHD_Open(CHD.UNI, 0) then
    CHD_Go(t, ti, CHD.UNI, 0)                 -- team name RIGHT -> kit
  elseif hdr and f == CHD.DECK and t == CHD.NAME and CHD_Open(CHD.UNI, 0) then
    CHD_Go(t, ti, CHD.UNI, 0)                 -- player plate LEFT -> kit
  elseif hdr and f == CHD.UNI and t == CHD.FORM then
    CHD_Go(t, ti, CHD.UNI, 0)                 -- kit UP: nothing above it in the header
  elseif hdr and f == CHD.UNI and t == CHD.CONF and CHD_Open(CHD.NAME, 0) then
    CHD_Go(t, ti, CHD.NAME, 0)                -- kit LEFT -> team name
  elseif f == CHD.FORM and t == CHD.TAC and CHD_TacOn() and CHD_Open(CHD.TAC, 2) then
    CHD_Go(t, ti, CHD.TAC, 2)                 -- FORMACIÓN UP -> left tactic box
  elseif f == CHD.FORM and t == CHD.CONF then
    if hdr then
      CHD_FormDown(t, ti)                     -- FORMACIÓN DOWN: the card below, else FORMACIÓN stays
    elseif CHD_Open(CHD.UNI, 0) then
      CHD_Go(t, ti, CHD.UNI, 0)               -- panel mode: the kit under the panel
    end
  elseif f == CHD.CONF and t == CHD.FORM and CHD_Open(CHD.TAC, 0) then
    CHD_Go(t, ti, CHD.TAC, 0)                 -- CONF. UP -> right tactic box
  elseif f == CHD.CONF and t == CHD.UNI then
    CHD_ConfToPitch(t, ti)                    -- CONF. RIGHT -> the pitch
  elseif f == CHD.TAC and t == CHD.FORM and fi == 0 and CHD_TacOn() and CHD_ConfShown() then
    CHD_Go(t, ti, CHD.CONF, 0)                -- right tactic box DOWN -> CONF.
  end
end

-- a D-pad / arrow / stick step this frame (the input a key shift row answers)
local function CHD_NavKey()
  return CHD_Key(CHD.CMD_DOWN) or CHD_Key(CHD.CMD_UP) or CHD_Key(CHD.CMD_LEFT) or CHD_Key(CHD.CMD_RIGHT)
end

-- 2026-10-13 (owner video: FORMACIÓN DOWN lit CONF. DE EQUIPO for one frame, then FORMACIÓN again). The key shift row
-- (nie 0x10DC7B0) moves the control focus, the mark / focus-in and the sound to its target and calls this callback as
-- its LAST step (vtable 0x168 -> 0x10C9710), then the input is done; the Step runs before the input in a frame, so a
-- redirect on the next Step let the retail target render for one frame. A key shift is now redirected here, before
-- that frame is drawn. The pointer's group switch (0x535F80, OnMouseMove) also calls this callback but sets its focus
-- AFTER it, so a shift without a D-pad / arrow / stick step this frame keeps the next-Step redirect.
local chd_prev_shift = rawget(_ENV, "OnFocusLayerShift")
if type(chd_prev_shift) == "function" then
  rawset(_ENV, "OnFocusLayerShift", function(a1, a2, a3, a4, ...)
    local r = CHD_Pack(chd_prev_shift(a1, a2, a3, a4, ...))
    if not CHD.going and CHD_PanelOn() then
      local sh = {a1, a2, a3, a4}
      local now = not CHD.busy and CHD_NavKey()
      if CHD.moves < 80 then
        CHD.moves = CHD.moves + 1
        CHD_Log("shift " .. tostring(a1) .. "[" .. tostring(a2) .. "] -> " .. tostring(a3) .. "[" .. tostring(a4) .. "]"
          .. (now and " (key: redirected now)" or " (redirect on the next Step)"))
      end
      if now then
        CHD.shift = nil
        local ok, err = pcall(CHD_Redirect, sh)
        if not ok then
          CHD_Log("error shift redirect " .. tostring(err))
        end
      else
        CHD.shift = sh
      end
    end
    return table.unpack(r, 1, r.n)
  end)
end

CHD_After("Step", function()
  if CHD_PanelOn() and not CHD.busy then
    CHD_Decide()
    CHD_Check()
    if CHD.shift ~= nil then
      local sh = CHD.shift
      CHD.shift = nil
      CHD_Redirect(sh)
    end
    CHD_Poll()
    if CHD_ClipOn() then
      CHD_Clip()
    end
    CHD_FixKit()
    CHD_PointerGuard()
    CHD.BoxGuard()
  end
  if not CHD.busy then
    CHD_Atdf()
  end
  if not CHD.busy then
    CHD_Ghost()
  end
end)
-- ===== EVT ui_clean_dock_panel END =====
